import subprocess, json, re

def ft2_call(name, args):
    cmd = ["ft2", "call", name, json.dumps(args)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    return result.stdout

def parse_cell(out):
    # Extract the JSON object from the response
    m = re.search(r'\{.*\}', out)
    if not m:
        return {}
    try:
        return json.loads(m.group(0))
    except:
        return {}

print("=== Checking pattern 0 row 0 ===")
for ch in range(8):
    out = ft2_call("pattern_get_cell", {"pattern":0,"row":0,"channel":ch})
    cell = parse_cell(out)
    if cell.get("note", 0) > 0 or cell.get("instrument", 0) > 0:
        print(f"ch{ch}: note={cell.get('note_name','')}, inst={cell.get('instrument')}, vol={cell.get('volume')}")

