for row in [60,61,62,63]:
    for ch in [0,1,2,3,4,5,6]:
        out = ft2_call("pattern_get_cell", {"pattern":3,"row":row,"channel":ch})
        cell = parse_cell(out)
        if cell.get("note", 0) > 0:
